class Solution:
    def numMatchingSubseq(self, s: str, words: List[str]) -> int:
        word_dict = defaultdict(list)
        numMatch = 0
        # add words into bucket with key as order of the first letter
        for w in words:
            word_dict[ord(w[0])-ord('a')].append(w)
        # loop through the characters in s
        for c in s:
            qualified = word_dict[ord(c)-ord('a')]
            word_dict[ord(c)-ord('a')] = []
            for q in qualified:
                # if the word starts with the specified letter. i.e this is the last letter of the word
                if len(q) == 1:
                    numMatch += 1
                else:
                    word_dict[ord(q[1])-ord('a')].append(q[1:])
        return numMatch

import collections

class Solution:
    def numMatchingSubseq(self, S, words):
        waiting = collections.defaultdict(list)
        for word in words:
            it = iter(word)
            waiting[next(it, None)].append(it)
        for c in S:
            for it in waiting.pop(c, ()):
                waiting[next(it, None)].append(it)
        return len(waiting[None])

class Solution:
    def preimageSizeFZF(self, k: int) -> int:  

        def atMost_k(k: int)-> int:

            left, right = 0, 5*k + 4

            while left <= right:
                mid = (left+right)//2
                count, n = 0, mid

                while n:
                    n//= 5
                    count+= n

                if count <= k: left = mid + 1
                else: right = mid - 1

            return right


        return atMost_k(k) - atMost_k(k-1)

class Solution:
    def preimageSizeFZF(self, K):
        def count_of_factorial_primes(n, p):
            cnt = 0
            while n > 0:
                cnt += n//p
                n //= p
            return cnt

        p = 5
        left, right = 0, p*K
        while left <= right:
            mid = left + (right-left)//2
            if count_of_factorial_primes(mid, p) >= K:
                right = mid-1
            else:
                left = mid+1
        return p if count_of_factorial_primes(left, p) == K else 0

