class Solution:
    def numSubarrayBoundedMax(self, nums: List[int], left: int, right: int) -> int:
        n = len(nums)
        stack = []
        next_greater = [n] * n
        prev_greater = [-1] * n
        for i in range(n):
            while len(stack) > 0 and nums[i] > nums[stack[-1]]:
                curr = stack.pop()
                next_greater[curr] = i
            if len(stack) > 0:
                prev_greater[i] = stack[-1]
            stack.append(i)
        res = 0
        for i in range(n):
            if left <= nums[i] <= right:
                l = prev_greater[i]
                r = next_greater[i]
                res += (i - l) * (r - i)
        return res

class Solution:
    def numSubarrayBoundedMax(self, A, L, R):
        def count(A, bound):
            result, curr = 0, 0
            for i in A :
                curr = curr + 1 if i <= bound else 0
                result += curr
            return result

        return count(A, R) - count(A, L-1)

